public ModifyMobBehaviorPower(PowerType<?> type, LivingEntity entity, Predicate<Pair<Entity, Entity>> bientityCondition, MobBehavior mobBehavior) {
    super(type, entity);
    this.bientityCondition = bientityCondition;
    this.mobBehavior = mobBehavior;
    this.addMobPredicate(pair -> doesApply(pair.getLeft(), pair.getRight()));
    this.addPowerHolderPredicate(livingEntity -> this.getType().isActive(livingEntity));
    this.setTicking(true);
}

public boolean doesApply(LivingEntity powerHolder, LivingEntity mob) {
    return this.bientityCondition == null || this.bientityCondition.test(new Pair<>(powerHolder, mob));
}

public void addMobPredicate(Predicate<Pair<LivingEntity, LivingEntity>> predicate) {
    mobBehavior.addMobRelatedPredicate(predicate);
}

public void addPowerHolderPredicate(Predicate<LivingEntity> predicate) {
    mobBehavior.addEntityRelatedPredicate(predicate);
}

public MobBehavior getMobBehavior() {
    return mobBehavior;
}

public static PowerFactory<?> getFactory() {
    return new PowerFactory<ModifyMobBehaviorPower>(Apugli.identifier("modify_mob_behavior"),
            new SerializableData()
                    .add("bientity_condition", ApoliDataTypes.BIENTITY_CONDITION, null)
                    .add("behavior", ApugliDataTypes.MOB_BEHAVIOR),
            data ->
                    (type, player) -> new ModifyMobBehaviorPower(type, player, data.get("bientity_condition"), data.get("behavior")))
            .allowCondition();
}

public void removeGoals(MobEntity mob) {
    ((MobEntityAccess)mob).getModifiedTargetSelectorGoals().stream().filter(pair -> pair.getLeft() == this).forEach(pair -> ((MobEntityAccessor)mob).getTargetSelector().remove(pair.getRight()));
    ((MobEntityAccess)mob).getModifiedTargetSelectorGoals().removeIf(pair -> pair.getLeft() == this);
    ((MobEntityAccess)mob).getModifiedGoalSelectorGoals().stream().filter(pair -> pair.getLeft() == this).forEach(pair -> ((MobEntityAccessor)mob).getGoalSelector().remove(pair.getRight()));
    ((MobEntityAccess)mob).getModifiedGoalSelectorGoals().removeIf(pair -> pair.getLeft() == this);
}

public boolean hasAppliedGoals(MobEntity mob) {
    return ((MobEntityAccess)mob).getModifiedTargetSelectorGoals().stream().filter(pair -> pair.getLeft() == this).toList().size() > 0 || ((MobEntityAccess)mob).getModifiedGoalSelectorGoals().stream().filter(pair -> pair.getLeft() == this).toList().size() > 0;
}

public void addMobRelatedPredicate(Predicate<Pair<LivingEntity, LivingEntity>> predicate) {
    mobRelatedPredicates = mobRelatedPredicates == null ? predicate : mobRelatedPredicates.and(predicate);
}

public void addEntityRelatedPredicate(Predicate<LivingEntity> predicate) {
    entityRelatedPredicates = entityRelatedPredicates == null ? predicate : entityRelatedPredicates.and(predicate);
}

@Override
public void initGoals(MobEntity mob) {
    if (!(mob instanceof PathAwareEntity)) return;
    Goal fleeGoal = new FleeEntityGoal<>((PathAwareEntity) mob, LivingEntity.class, fleeDistance, this.slowSpeed, this.fastSpeed, entity ->
            mobRelatedPredicates.test(new Pair<>(entity, mob)) && entityRelatedPredicates.test(entity));
    ((MobEntityAccessor)mob).getGoalSelector().add(this.priority, fleeGoal);
    ((MobEntityAccess)mob).getModifiedTargetSelectorGoals().add(new Pair<>(this, fleeGoal));
}

